window.LD=window.LD||{};window.LD["party/p5"]={"id":"p5","name":"The Black Vanguard","poss":"The Black Vanguard's","members":["h12","h8","h6"],"leader":"h12","morale":90,"disposition":"territorial","motto":"Fear is for other parties.","banner":{"c1":"#2b2b33","c2":"#7a4cc8","emblem":"shield"},"loc":"veldrock","loc_name":"Veldrock","goal":{"text":"to earn 3,050 silver between them before the season ends","kind":"purse","done":null,"progress":"2,974 of 3,050 silver","missed":true,"crew":"The Black Vanguard","party":"p5"},"vows":[{"text":"never to retreat","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Black Vanguard","party":"p5"}],"doing":"last seen escort","progress":null,"today":["XP: Ash +220, Hazel +184, Tobias +184.","Coin between them: +11 silver.","Came away with 3 rations."],"fights_today":[],"why":null,"founded_day":2,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"answer_the_horn","title":"Answer the Horn","tone":"heroic","meter":"3/4","bpm":101,"diff":3,"day":65,"night":"n107","n":4,"by":null,"lead":{"id":"h8","name":"Hazel","skill":0.79,"inst":"fiddle"}},"renown":345,"season":{"wins":12,"bosses":0,"floors":4,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":8},"career":{"wins":33,"bosses":1,"floors":13,"gold":0,"deaths":0,"fled":2,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":89,"arguments":17},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"ox_wagon","name":"Last Penny","label":"ox wagon","seats":5,"haul":70,"comfort":0,"since":19,"desc":"Slow as a wedding, carries a house.","moves":true,"puller":{"kind":"ox","name":"Bertha","label":"ox","colour":"black","owner":null},"paid":[["Hazel",57],["Ash",19]]},"pace_gap":0,"rels":[{"party":"p2","score":100},{"party":"p1","score":44},{"party":"p4","score":16},{"party":"p3","score":1}],"events":[{"id":"e389","day":10,"season":1,"sday":10,"kind":"big_move","imp":4,"text":"The Black Vanguard brings down Old Grizzlemaw, a Wolf and a Dire Wolf at the bottom of the Wolf Den and lives to tell of it. On the table: The Black Vanguard +102 party renown (3rd to 1st among the crews).","heroes":["h12","h8","h6"],"parties":["p5"],"party_moves":[{"party":"p5","gain":102,"from":3,"to":1}],"cause":"e363","fight":"f48"},{"id":"e692","day":18,"season":1,"sday":18,"kind":"goal_done","imp":4,"text":"GOAL: The Black Vanguard set out to see the world: 6 different places before the season ends, and they have done it, with 12 days to spare. It was Tobias's idea in the first place. XP: Ash +800 (level 11!), Hazel +800 (level 11!), Tobias +800 (level 11!).","heroes":["h12","h8","h6"],"parties":["p5"],"xp":{"h12":800,"h8":800,"h6":800}},{"id":"e775","day":21,"season":1,"sday":21,"kind":"delve","imp":1,"text":"The Black Vanguard descends into Thornmere Ruins, untouched (0%).","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e776","day":21,"season":1,"sday":21,"kind":"fight","imp":3,"text":"Tobias hits hardest as the Black Vanguard handles 2 Bog Crawlers, 2 Swamp Trolls and a Will-o'-Wisp on floor 1 of Thornmere Ruins. Tobias tied up the bog crawler with Rootbound Ground at just the right moment. Ask the others what won it: Ash's Divine Shield. Loot: 26 silver each, 2 bog crawler claws, 3 troll hide.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f82","foes":["bog_crawler","swamp_troll","wisp"],"where":"on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-23,"wx":"rain"},{"id":"e800","day":21,"season":1,"sday":21,"kind":"tarot","imp":1,"text":"Tobias lays three cards on a flat stone for The Black Vanguard, with Thornmere Ruins a short walk off in the dark: the Two of Wands, the Ten of Cups and the Hierophant. Nothing to worry about, says Tobias.","heroes":["h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","reading":"r161","wx":"rain"},{"id":"e806","day":21,"season":1,"sday":21,"kind":"campfire","imp":1,"text":"Ash learns how Tobias takes wine. It's a small thing. It's noticed.","heroes":["h12","h6"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e820","day":22,"season":1,"sday":22,"kind":"treasure","imp":3,"text":"A dead adventurer on floor 1 of Thornmere Ruins won't be needing 476 silver, a gem and a bog crawler claw any more. Hazel takes it, with thanks.","heroes":["h8","h12","h6"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e821","day":22,"season":1,"sday":22,"kind":"talent","imp":2,"text":"Tobias lies down in the grass and the grass, very gently, holds them there till morning. Rootbound Ground all the way, Tobias insists.","heroes":["h6"],"parties":["p5"],"loc":"thornmere_ruins","skill":"rootbound_ground","wx":"rain"},{"id":"e860","day":23,"season":1,"sday":23,"kind":"treasure","imp":1,"text":"Behind a loose stone on floor 1 of Thornmere Ruins, Ash finds 307 silver and a bog crawler claw.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e861","day":23,"season":1,"sday":23,"kind":"talent","imp":1,"text":"Hazel works out the final chord of a new song. Tobias hums it all evening. Crescendo, the guild calls it.","heroes":["h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","skill":"crescendo","wx":"rain"},{"id":"e889","day":24,"season":1,"sday":24,"kind":"fight","imp":1,"text":"On floor 2 of Thornmere Ruins, the Black Vanguard squares up to 2 Will-o'-Wisps and a Swamp Troll and carries the day. Ash picked out the will-o'-wisp and finished the job with Turn Undead. Loot: 16 silver each, 2 bottled wisplight, 2 wisp sugar.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f93","foes":["wisp","swamp_troll","wisp"],"where":"on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-15,"wx":"rain"},{"id":"e890","day":24,"season":1,"sday":24,"kind":"treasure","imp":1,"text":"A dead adventurer on floor 2 of Thornmere Ruins won't be needing 167 silver and a drake flank any more. Tobias takes it, with thanks.","heroes":["h6","h12","h8"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e898","day":24,"season":1,"sday":24,"kind":"argument","imp":2,"text":"Ash says one thing too many about Tobias's cooking. Tobias says two.","heroes":["h12","h6"],"parties":["p5"]},{"id":"e900","day":24,"season":1,"sday":24,"kind":"campfire","imp":2,"text":"Ash saves Hazel the good spot by the fire. Again.","heroes":["h12","h8"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e904","day":25,"season":1,"sday":25,"kind":"fight","imp":2,"text":"Two Swamp Trolls, a Bog Crawler and a Siren are waiting on floor 3 of Thornmere Ruins, and the Black Vanguard barely beats them. Hazel put Crescendo where it would hit four of them, and it did. Loot: 25 silver each, 4 troll hide, 7 herbs.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f94","foes":["swamp_troll","swamp_troll","bog_crawler"],"where":"on floor 3 of Thornmere Ruins","won":true,"close":true,"shape":"foe","reworded":-24,"wx":"rain"},{"id":"e905","day":25,"season":1,"sday":25,"kind":"talent","imp":2,"text":"Ash shares supper with two pilgrims and their goat. The goat eats Tobias's bootlace. (The Pilgrims' Escort, if anyone's asking.)","heroes":["h12","h6"],"parties":["p5"],"loc":"thornmere_ruins","skill":"pilgrims_escort","wx":"rain"},{"id":"e917","day":25,"season":1,"sday":25,"kind":"bond","imp":3,"text":"The Azure Gravediggers and The Black Vanguard are rivals now, starting with Morwen and Hazel.","heroes":["h5","h8"],"parties":["p3","p5"],"bond":"rivals"},{"id":"e936","day":26,"season":1,"sday":26,"kind":"fight","imp":3,"text":"The Black Vanguard is routed by 2 Swamp Trolls and 2 Drakes on floor 4 of Thornmere Ruins and runs for it. Ash was the last one out and the angriest about it. Injured: Ash (bruised ribs).","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f100","foes":["swamp_troll","swamp_troll","drake"],"where":"on floor 4 of Thornmere Ruins","won":false,"close":true,"shape":"plain","wx":"rain"},{"id":"e937","day":26,"season":1,"sday":26,"kind":"delve_done","imp":1,"text":"Driven out, The Black Vanguard climbs out of Thornmere Ruins after 6 days. They got all the way to the bottom, mapped 33% of it and came away with 1146 silver between them. Counting everyone's digging, Thornmere Ruins is mostly unexplored (25%).","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","days":6,"bottom":true,"rooms":[],"gold":1146,"out":"Driven out","wx":"rain"},{"id":"e938","day":26,"season":1,"sday":26,"kind":"talent","imp":1,"text":"Hazel resoles Ash's boots overnight. Ash walks the next day like a different person.","heroes":["h8","h12"],"parties":["p5"],"loc":"thornmere_ruins","skill":"cobbler","wx":"rain"},{"id":"e958","day":26,"season":1,"sday":26,"kind":"talent","imp":1,"text":"A root as thick as an arm cracks through the dungeon floor to trip a charging rat, then waves at Tobias. Rootbound Ground: one of the things Tobias learned the long way round.","heroes":["h6"],"parties":["p5"],"loc":"thornmere_ruins","skill":"rootbound_ground","wx":"rain"},{"id":"e964","day":26,"season":1,"sday":26,"kind":"campfire","imp":1,"text":"Hazel slips Clementine a sausage under the table. Ash sees, and decides Hazel is all right.","heroes":["h12","h8"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e980","day":27,"season":1,"sday":27,"kind":"night","imp":2,"text":"Ash tells a ghost story by the fire in Bleakmarsh. Tobias sleeps with a hand on their weapon.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"bleakmarsh","wx":"rain"},{"id":"e991","day":27,"season":1,"sday":27,"kind":"talent","imp":1,"text":"Hazel bets Tobias a silver that the next cart will be pulled by a mule. It's a mule. Tobias pays up, grumbling.","heroes":["h8","h6"],"parties":["p5"],"loc":"bleakmarsh","skill":"gambler","wx":"rain"},{"id":"e1001","day":27,"season":1,"sday":27,"kind":"argument","imp":1,"text":"Tobias says one thing too many about the ethics of looting bodies. Ash says two.","heroes":["h6","h12"],"parties":["p5"]},{"id":"e1039","day":28,"season":1,"sday":28,"kind":"talent","imp":1,"text":"Ash joins the Carrbridge temple choir for a service and is asked to come back on holy days.","heroes":["h12"],"parties":["p5"],"loc":"carrbridge","skill":"hymn_singer","wx":"rain"},{"id":"e1051","day":28,"season":1,"sday":28,"kind":"ledger","imp":2,"text":"Counters and coin this week: 11 sales, 898 silver changing hands. Biggest haul: Bramble, 138 silver in Ashfen. Back up from the deep: The Black Vanguard (6 days in Thornmere Ruins), The Newts of Ashfen (7 days in the Ashveil Crypts).","heroes":["h13","h12"],"parties":["p5","p1"]},{"id":"e1109","day":30,"season":1,"sday":30,"kind":"campfire","imp":3,"text":"Ash catches Tobias humming and doesn't say anything. That's a start.","heroes":["h6","h12"],"parties":["p5"],"loc":"carrbridge","wx":"rain"},{"id":"e1148","day":31,"season":2,"sday":1,"kind":"contract","imp":2,"text":"The Black Vanguard takes a clearing job in Frosthold: 8 ice wraiths out of Whitepeak Pass by day 8 of season 2.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"frosthold","wx":"snow"},{"id":"e1149","day":31,"season":2,"sday":1,"kind":"talent","imp":1,"text":"Ash banks the fire so there are still coals at dawn. Breakfast is twenty minutes sooner. Firekeeper all the way, Ash insists.","heroes":["h12"],"parties":["p5"],"loc":"whitepeak","skill":"firekeeper","wx":"snow"},{"id":"e1150","day":31,"season":2,"sday":1,"kind":"night","imp":2,"text":"A child turns up at The Black Vanguard's camp in Whitepeak Pass, announces that Frostspire \"eats lanterns\", and runs off before anyone can ask what that means.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"whitepeak","wx":"snow"},{"id":"e1157","day":31,"season":2,"sday":1,"kind":"ability","imp":2,"text":"Ash and Hazel escort a family of travellers past Whitepeak Pass. Nothing happens, which is the point. They're paid 24 silver for it.","heroes":["h12","h8"],"parties":["p5"],"loc":"whitepeak","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true,"wx":"snow"},{"id":"e1158","day":31,"season":2,"sday":1,"kind":"talent","imp":2,"text":"Tobias asks a bramble patch to let the party through. It thinks about it, then does. (Rootbound Ground, if anyone's asking.)","heroes":["h6"],"parties":["p5"],"loc":"whitepeak","skill":"rootbound_ground","wx":"snow"},{"id":"e1167","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Tobias admits to being afraid of the dark. Hazel doesn't laugh. Hazel just nods and takes the watch nearest it.","heroes":["h8","h6"],"parties":["p5"],"loc":"whitepeak","wx":"snow"},{"id":"e1171","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"A vow from The Black Vanguard: never to retreat. Easy to say on day one.","heroes":["h12","h8","h6"],"parties":["p5"]},{"id":"e1186","day":32,"season":2,"sday":2,"kind":"fight","imp":2,"text":"Ash takes the worst of it as the Black Vanguard makes short work of 5 Ice Wraiths in Whitepeak Pass. Ash cleared four ice wraiths with a single Turn Undead. Loot: 15 ectoplasm, 9 wraith-frost, 5 frost crystals. Injured: Ash (sprained ankle).","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"whitepeak","fight":"f112","foes":["ice_wraith","ice_wraith","ice_wraith"],"where":"in Whitepeak Pass","won":true,"close":false,"shape":"hero","reworded":-29},{"id":"e1187","day":32,"season":2,"sday":2,"kind":"talent","imp":1,"text":"Hazel plays something soft at the fire until even Tobias stops pretending not to listen. The bard's trade has a name for that: Tavern Star.","heroes":["h8","h6"],"parties":["p5"],"loc":"whitepeak","skill":"tavern_star"},{"id":"e1205","day":32,"season":2,"sday":2,"kind":"campfire","imp":1,"text":"Ash and Hazel see in a month of The Black Vanguard by splitting the last good bottle. Nobody else is offered any.","heroes":["h12","h8"],"parties":["p5"],"loc":"whitepeak"},{"id":"e1206","day":32,"season":2,"sday":2,"kind":"talent","imp":1,"text":"It's raining sideways and Ash gets the fire lit on the second spark. The crew cheers like it's a boss kill.","heroes":["h12"],"parties":["p5"],"loc":"whitepeak","skill":"firekeeper"},{"id":"e1207","day":32,"season":2,"sday":2,"kind":"campfire","imp":1,"text":"Ash pulls an arrow out of Hazel's shield and hands it back like a gift.","heroes":["h12","h8"],"parties":["p5"],"loc":"whitepeak"},{"id":"e1213","day":33,"season":2,"sday":3,"kind":"fight","imp":2,"text":"The Black Vanguard, in fine spirits lately, sees off 3 Ice Wraiths and a Yeti in Whitepeak Pass. Three ice wraiths went down together, and they have Ash's Turn Undead to thank. Without Hazel's Marching Song, this goes differently. Loot: 6 ectoplasm, 6 pelts, 2 frost crystals.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"whitepeak","fight":"f116","foes":["ice_wraith","yeti","ice_wraith"],"where":"in Whitepeak Pass","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e1214","day":33,"season":2,"sday":3,"kind":"contract","imp":3,"text":"The farmers near Frosthold can use the north road again: The Black Vanguard has thinned the ice wraiths in Whitepeak Pass. 54 silver each.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"whitepeak"},{"id":"e1215","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Hazel challenges Ash to a singing contest by the fire, loser on washing-up. Hazel wins, loudly.","heroes":["h8","h12"],"parties":["p5"],"loc":"whitepeak","skill":"mead_hall"},{"id":"e1216","day":33,"season":2,"sday":3,"kind":"night","imp":1,"text":"Something small and clever gets into The Black Vanguard's camp in Whitepeak Pass overnight. Ash wakes up 9 silver and 3 rations lighter.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"whitepeak"},{"id":"e1263","day":34,"season":2,"sday":4,"kind":"campfire","imp":1,"text":"Thirty days in The Black Vanguard. Ash and Tobias have stopped keeping score of who owes whom.","heroes":["h12","h6"],"parties":["p5"],"loc":"frosthold"},{"id":"e1265","day":34,"season":2,"sday":4,"kind":"campfire","imp":1,"text":"Hazel and Tobias, a month into The Black Vanguard: they walk in step now without trying.","heroes":["h8","h6"],"parties":["p5"],"loc":"frosthold"},{"id":"e1280","day":35,"season":2,"sday":5,"kind":"night_game","imp":2,"text":"The bandit puts down its weapon, rolls up a sleeve and says Tobias looks like a Crooked Cards sort of person. The bandit loses at Crooked Cards with enormous dignity, then digs out Bandit's Hidden Coin and presses it into Tobias's hand. Hazel says it is a fine thing to be robbed by somebody who shakes your hand afterwards.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"ironhaven","night":"n62","monster_game":"bandit","wx":"fog"},{"id":"e1287","day":35,"season":2,"sday":5,"kind":"talent","imp":1,"text":"Tobias casts a line from every bridge on the route. At the fourth, a pike. Tobias names it.","heroes":["h6"],"parties":["p5"],"loc":"frosthold","skill":"angler"},{"id":"e1288","day":35,"season":2,"sday":5,"kind":"talent","imp":1,"text":"Hazel keeps the marching pace with a song that just gets louder. Crescendo, the guild calls it.","heroes":["h8"],"parties":["p5"],"loc":"frosthold","skill":"crescendo"},{"id":"e1324","day":36,"season":2,"sday":6,"kind":"road","imp":3,"text":"Tobias is surprised to find a ridge on Ines's map marked with their own name. She has been drawing it all week.","heroes":["h6","h12","h8"],"parties":["p5"],"road":"frosthold~ironhaven","traveller":"ines","road_rec":"r240"},{"id":"e1336","day":36,"season":2,"sday":6,"kind":"argument","imp":2,"text":"The Black Vanguard spends the evening listening to Hazel and Ash argue about the party's name.","heroes":["h8","h12"],"parties":["p5"]},{"id":"e1381","day":38,"season":2,"sday":8,"kind":"contract","imp":2,"text":"The Black Vanguard agrees to fetch a dead knight's signet ring from floor 3 of Thornmere Ruins. The family is very insistent.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"ironhaven","wx":"fog"},{"id":"e1382","day":38,"season":2,"sday":8,"kind":"road","imp":3,"text":"Tobias follows Lady Perpetua Vane down the wrong road for half a day, because it would be rude not to.","heroes":["h6","h12","h8"],"parties":["p5"],"road":"carrbridge~ironhaven","traveller":"perpetua","road_rec":"r255"},{"id":"e1385","day":38,"season":2,"sday":8,"kind":"boss_race","imp":3,"text":"Word in the taverns: Amber Banner and The Black Vanguard are both after Mother Thornmere. Thornmere Ruins has one way down and room for one winner.","heroes":["h18","h4","h2","h12","h8","h6"],"parties":["p2","p5"],"loc":"thornmere_ruins"},{"id":"e1393","day":38,"season":2,"sday":8,"kind":"argument","imp":4,"text":"Enough is enough: Ash tells Tobias exactly what everyone in The Black Vanguard has been thinking. Nobody sleeps.","heroes":["h6","h12"],"parties":["p5"]},{"id":"e1394","day":38,"season":2,"sday":8,"kind":"campfire","imp":2,"text":"Ash offers Tobias the dry side of the tent. Tobias accepts, suspiciously.","heroes":["h12","h6"],"parties":["p5"],"loc":"carrbridge","wx":"fog"},{"id":"e1414","day":39,"season":2,"sday":9,"kind":"road","imp":3,"text":"Old Maudie counts the cows and comes up short: Tuesday is missing. Hazel is deputised on the spot and hands over a quarter hour of road.","heroes":["h8","h12","h6"],"parties":["p5"],"road":"bleakmarsh~carrbridge","traveller":"maudie","road_rec":"r263"},{"id":"e1426","day":39,"season":2,"sday":9,"kind":"talent","imp":2,"text":"Ash drizzles wild honey over the porridge. Hazel looks at Ash as if Ash invented joy. Honey Finder all the way, Ash insists.","heroes":["h12","h8"],"parties":["p5"],"loc":"bleakmarsh","skill":"honey_finder"},{"id":"e1458","day":40,"season":2,"sday":10,"kind":"meet","imp":2,"text":"The Black Vanguard runs into Amber Banner in Thornmere Ruins. Stories are exchanged, most of them exaggerated.","heroes":["h12","h8","h6","h18","h4","h2"],"parties":["p5","p2"],"loc":"thornmere_ruins"},{"id":"e1468","day":41,"season":2,"sday":11,"kind":"delve","imp":1,"text":"The Black Vanguard descends into Thornmere Ruins, mostly unexplored (33%), map in hand.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1469","day":41,"season":2,"sday":11,"kind":"fight","imp":1,"text":"On floor 1 of Thornmere Ruins, the Black Vanguard beats 3 Will-o'-Wisps. Hazel's Crescendo took down two will-o'-wisps at once. Loot: 6 bottled wisplight, 2 wisp sugar.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f138","foes":["wisp","wisp","wisp"],"where":"on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e1470","day":41,"season":2,"sday":11,"kind":"treasure","imp":2,"text":"Tobias jimmies open a chest on floor 1 of Thornmere Ruins: 78 silver and an old Lampstone Dice.","heroes":["h6","h12","h8"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1482","day":41,"season":2,"sday":11,"kind":"tarot","imp":2,"text":"Tobias lays three cards on a flat stone for The Black Vanguard, with Thornmere Ruins a short walk off in the dark: the Page of Cups, the Seven of Pentacles and the Nine of Swords upside down. A good spread, all told.","heroes":["h12","h6"],"parties":["p5"],"loc":"thornmere_ruins","reading":"r277"},{"id":"e1491","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"The Black Vanguard's plan for the season, as told to the barkeep: to finish the season as one of the top three parties.","heroes":["h12","h8","h6"],"parties":["p5"]},{"id":"e1501","day":42,"season":2,"sday":12,"kind":"fight","imp":2,"text":"Nothing about it is easy, but the Black Vanguard scrapes past 2 Will-o'-Wisps and 2 Swamp Trolls on floor 2 of Thornmere Ruins. Two will-o'-wisps went down together, and they have Hazel's Crescendo to thank. Ask the others what won it: Ash's Divine Shield. (Brother Toad's blessing on Ash seems to have held.) Loot: 21 silver each, 4 bottled wisplight, 2 wisp sugar.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f142","foes":["wisp","wisp","swamp_troll"],"where":"on floor 2 of Thornmere Ruins","won":true,"close":true,"shape":"close","reworded":-30},{"id":"e1521","day":42,"season":2,"sday":12,"kind":"campfire","imp":1,"text":"Hazel talks Ash through a bad night about the dark. Neither mentions it in the morning. Both remember.","heroes":["h8","h12"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1534","day":43,"season":2,"sday":13,"kind":"contract","imp":3,"text":"Found it: on floor 3 of Thornmere Ruins, under a heap of bones, The Black Vanguard recovers a dead knight's signet ring. Ironhaven pays 78 each.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1535","day":43,"season":2,"sday":13,"kind":"talent","imp":1,"text":"Tobias prises the hidden coin open by the fire. Empty. The bandit must have spent what was in it.","heroes":["h6"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1536","day":43,"season":2,"sday":13,"kind":"ambush","imp":2,"text":"The Black Vanguard makes it five wins running, defeating 3 Will-o'-Wisps at their camp in Thornmere Ruins, in the middle of the night. The last will-o'-wisp doesn't stay to see the end. Hazel's Crescendo dropped two will-o'-wisps before they reached the line. Hazel's Marching Song kicked in when it counted. Tobias stopped to read the writing on the walls and is now worried about it. \"Somewhere, a song just started,\" says Tobias. Loot: 2 bottled wisplight.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f151","foes":["wisp","wisp","wisp"],"where":"at their camp in Thornmere Ruins, in the middle of the night","won":true,"close":false,"shape":"streak","reworded":-52},{"id":"e1571","day":44,"season":2,"sday":14,"kind":"fight","imp":3,"text":"Two Sirens are waiting on floor 3 of Thornmere Ruins, and the Black Vanguard makes short work of them. The last siren takes off and isn't seen again. Tobias' Thorn Whip took most of the fight out of the siren in one go. Entangle, from Tobias, at exactly the right moment. Loot: 1 gem, 5 sea grapes.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f158","foes":["siren","siren"],"where":"on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-49},{"id":"e1572","day":44,"season":2,"sday":14,"kind":"treasure","imp":1,"text":"A dead adventurer on floor 3 of Thornmere Ruins won't be needing 16 gold pieces, 72 silver and a troll haunch any more. Ash takes it, with thanks.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1601","day":45,"season":2,"sday":15,"kind":"treasure","imp":1,"text":"Hazel insists on checking one more passage on floor 3 of Thornmere Ruins, and it opens onto a drowned wing of the temple: 47 silver.","heroes":["h8","h12","h6"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1602","day":45,"season":2,"sday":15,"kind":"night","imp":2,"text":"Something small and clever gets into The Black Vanguard's camp in Thornmere Ruins overnight. Hazel wakes up 7 silver and 3 rations lighter.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1619","day":46,"season":2,"sday":16,"kind":"fight","imp":1,"text":"Ash takes the worst of it as the Black Vanguard makes short work of a Swamp Troll on floor 3 of Thornmere Ruins. Ash had the last word, and the word was Radiance. Ash kept them off everyone with Divine Shield. Loot: 16 silver each, 1 troll hide, 5 herbs.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f166","foes":["swamp_troll"],"where":"on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-29},{"id":"e1630","day":46,"season":2,"sday":16,"kind":"sniped","imp":3,"text":"Word reaches The Black Vanguard on floor 3 of Thornmere Ruins: Amber Banner killed Mother Thornmere today. Nobody says much. The side passages still need mapping.","heroes":["h12","h8","h6","h18","h4","h2"],"parties":["p5","p2"],"loc":"thornmere_ruins","snipers":["h18","h4","h2"],"where":"inside","boss":"Mother Thornmere","in_fight":"f168"},{"id":"e1644","day":46,"season":2,"sday":16,"kind":"argument","imp":3,"text":"It starts with whose idea the last dungeon was. It ends with Tobias and Hazel sleeping on opposite sides of the fire.","heroes":["h6","h8"],"parties":["p5"]},{"id":"e1651","day":47,"season":2,"sday":17,"kind":"delve_done","imp":3,"text":"The Black Vanguard comes up after 7 days in Thornmere Ruins. They got down to floor 3, mapped 75% of it, found a drowned wing of the temple, disarmed 2 traps and came away with 690 silver between them. Not the trip they set out on, but a trip. Counting everyone's digging, Thornmere Ruins is picked clean (91%).","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","days":7,"bottom":false,"rooms":["a drowned wing of the temple"],"gold":690},{"id":"e1659","day":47,"season":2,"sday":17,"kind":"meet","imp":2,"text":"The Newts of Ashfen run into The Black Vanguard in Thornmere Ruins. Stories are exchanged, most of them exaggerated.","heroes":["h13","h7","h12","h8","h6"],"parties":["p1","p5"],"loc":"thornmere_ruins"},{"id":"e1660","day":47,"season":2,"sday":17,"kind":"talent","imp":2,"text":"Hazel hums under their breath in the dark. The party moves in step without meaning to. Somebody asks how. 'Crescendo,' says Hazel.","heroes":["h8"],"parties":["p5"],"loc":"thornmere_ruins","skill":"crescendo"},{"id":"e1678","day":48,"season":2,"sday":18,"kind":"meet","imp":1,"text":"Amber Banner runs into The Black Vanguard in Bleakmarsh. Stories are exchanged, most of them exaggerated.","heroes":["h18","h4","h2","h12","h8","h6"],"parties":["p2","p5"],"loc":"bleakmarsh"},{"id":"e1680","day":48,"season":2,"sday":18,"kind":"ability","imp":2,"text":"Ash finds two lost children on the road past Bleakmarsh and walks them home. Their grandmother pays 34 silver and shows Ash the shortcut nobody else knows.","heroes":["h12"],"parties":["p5"],"loc":"bleakmarsh","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true},{"id":"e1686","day":48,"season":2,"sday":18,"kind":"argument","imp":1,"text":"Hazel and Ash spend supper disagreeing about the party's name, politely at first.","heroes":["h8","h12"],"parties":["p5"]},{"id":"e1760","day":51,"season":2,"sday":21,"kind":"raid","imp":5,"text":"Thornwall is attacked at dusk by ice wraiths out of Frostspire, and Tobias, Hazel and Ash hold the gate. The town pays the defenders 25 silver each, and nobody in Thornwall will buy their own drink tonight.","heroes":["h6","h8","h12"],"parties":["p5"],"loc":"thornwall","fight":"f176"},{"id":"e1761","day":51,"season":2,"sday":21,"kind":"song","imp":3,"text":"Somebody at The Sagging Beam has written \"The Gate at Thornwall\", and now nobody in Thornwall can stop humming it.","heroes":["h6","h8","h12"],"parties":["p5"],"loc":"thornwall","song":"s51_21"},{"id":"e1794","day":51,"season":2,"sday":21,"kind":"gift","imp":2,"text":"By the fire, Tobias quietly hands Hazel a Bandit's Hidden Coin. Hazel pockets it like it's treasure.","heroes":["h6","h8"],"parties":["p5"],"loc":"thornwall"},{"id":"e1797","day":51,"season":2,"sday":21,"kind":"argument","imp":4,"text":"Ash and Hazel have had the same argument three times now. This time Ash threw a boot. The Black Vanguard is splitting into camps.","heroes":["h12","h8"],"parties":["p5"]},{"id":"e1824","day":52,"season":2,"sday":22,"kind":"road","imp":3,"text":"Marigold will not tell Hazel her secret ingredient, but lets them stir the pot once, which she says is nearly the same thing.","heroes":["h8","h12","h6"],"parties":["p5"],"road":"hollowood~thornwall","traveller":"marigold","road_rec":"r334"},{"id":"e1833","day":52,"season":2,"sday":22,"kind":"gift","imp":2,"text":"Ash buys Hazel a Gold Signet in Hollowood. No reason. Hazel wears it straight away.","heroes":["h12","h8"],"parties":["p5"],"loc":"hollowood"},{"id":"e1835","day":52,"season":2,"sday":22,"kind":"talent","imp":2,"text":"Tobias finds a Hollowood weed growing through the cobbles and quietly encourages it. (Rootbound Ground, if anyone's asking.)","heroes":["h6"],"parties":["p5"],"loc":"hollowood","skill":"rootbound_ground"},{"id":"e1879","day":53,"season":2,"sday":23,"kind":"talent","imp":1,"text":"Tobias carries Hazel's pack up the last hill as well as his own and only mentions it twice. Packmule: a ranger's patience, mostly.","heroes":["h6","h8"],"parties":["p5"],"loc":"hollowood","skill":"packmule"},{"id":"e1885","day":53,"season":2,"sday":23,"kind":"argument","imp":2,"text":"Ash and Tobias of The Black Vanguard have a shouting match about Tobias's cooking.","heroes":["h12","h6"],"parties":["p5"]},{"id":"e1906","day":54,"season":2,"sday":24,"kind":"talent","imp":1,"text":"Ash trades a jar of wild honey to a Thornwall healer for a pouch of dried herbs. Honey Finder, the way the old trappers taught it.","heroes":["h12"],"parties":["p5"],"loc":"thornwall","skill":"honey_finder"},{"id":"e1944","day":55,"season":2,"sday":25,"kind":"campfire","imp":1,"text":"Ash laughs at one of Tobias's jokes, then looks annoyed about it.","heroes":["h6","h12"],"parties":["p5"],"loc":"carrbridge"},{"id":"e1977","day":56,"season":2,"sday":26,"kind":"ability","imp":2,"text":"Bandits watch Ash lead a line of pilgrims past Bleakmarsh, look at their sword, and stay sitting down. At the shrine the pilgrims hand over 16 silver and a blessing apiece.","heroes":["h12"],"parties":["p5"],"loc":"bleakmarsh","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true},{"id":"e1995","day":57,"season":2,"sday":27,"kind":"fight","imp":3,"text":"In Bleakmarsh, the Black Vanguard dispatches a Bog Crawler and a Swamp Troll. Ash's Radiance left the swamp troll swinging at nothing. Loot: 8 silver each, 2 chitin, 2 bog crawler claws.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"bleakmarsh","fight":"f192","foes":["bog_crawler","swamp_troll"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e2014","day":57,"season":2,"sday":27,"kind":"campfire","imp":1,"text":"Hazel and Ash invent a scoring system for snoring. Nobody else is consulted.","heroes":["h8","h12"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e2027","day":58,"season":2,"sday":28,"kind":"fight","imp":1,"text":"It's a Will-o'-Wisp and Risen Dead against the Black Vanguard in Bleakmarsh, and it isn't close. Hazel waited for the gap and put Crescendo through it. Loot: 2 bottled wisplight, 2 wisp sugar, 2 remains.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"bleakmarsh","fight":"f195","foes":["wisp","zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"foe","reworded":-25,"wx":"rain"},{"id":"e2028","day":58,"season":2,"sday":28,"kind":"fight","imp":1,"text":"With Ash hitting hardest, the Black Vanguard defeats Risen Dead and a Will-o'-Wisp in Bleakmarsh. The risen dead went down to Tobias' Thorn Whip. Ash saved Divine Shield for when it mattered. Loot: 2 grave dust, 3 crypt-caps, 2 bottled wisplight.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"bleakmarsh","fight":"f196","foes":["zombie","wisp"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"hero","reworded":-26,"wx":"rain"},{"id":"e2039","day":58,"season":2,"sday":28,"kind":"meet","imp":2,"text":"Hazel and Vex swap stories in Bleakmarsh while The Black Vanguard and The Newts of Ashfen swap rumours.","heroes":["h12","h8","h6","h13","h7"],"parties":["p5","p1"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2065","day":59,"season":2,"sday":29,"kind":"night","imp":2,"text":"Something small and clever gets into The Black Vanguard's camp in Bleakmarsh overnight. Ash wakes up 10 silver and 3 rations lighter.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2076","day":59,"season":2,"sday":29,"kind":"argument","imp":2,"text":"Ash and Tobias of The Black Vanguard have a shouting match about Ash's habit of humming during ambushes.","heroes":["h12","h6"],"parties":["p5"]},{"id":"e2077","day":59,"season":2,"sday":29,"kind":"campfire","imp":1,"text":"Hazel orders Tobias a wine before Tobias even sits down. Remembering an order is how it starts.","heroes":["h6","h8"],"parties":["p5"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2112","day":60,"season":2,"sday":30,"kind":"campfire","imp":2,"text":"Ash keeps Hazel alive with one well-timed spell. Hazel buys the drinks for a week.","heroes":["h8","h12"],"parties":["p5"],"loc":"ashfen","wx":"rain"},{"id":"e2124","day":60,"season":2,"sday":30,"kind":"goal_missed","imp":3,"text":"Not this time: The Black Vanguard's goal (finish the season as one of the top three parties) falls short (finished 5th).","heroes":["h12","h8","h6"],"parties":["p5"]},{"id":"e2169","day":61,"season":3,"sday":1,"kind":"boss_race","imp":3,"text":"Somebody chalks a tally on the board for the race to Mother Thornmere's Brood: Amber Banner and The Black Vanguard. Odds are offered, mostly on whoever's buying.","heroes":["h18","h4","h2","h12","h8","h6"],"parties":["p2","p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e2177","day":61,"season":3,"sday":1,"kind":"journey","imp":2,"text":"The Black Vanguard and The Mercy of Thornwall walk to Carrbridge together. Someone brings up old scars. Someone always does.","heroes":["h12","h8","h6","h17","h11","h1"],"parties":["p5","p4"]},{"id":"e2186","day":61,"season":3,"sday":1,"kind":"campfire","imp":1,"text":"Hazel buys Ash a cheap swill. Then another. Then the conversation gets honest.","heroes":["h8","h12"],"parties":["p5"],"loc":"carrbridge"},{"id":"e2204","day":62,"season":3,"sday":2,"kind":"ambush","imp":2,"text":"The Black Vanguard handles 2 Swamp Trolls on the road to Bleakmarsh without much fuss. Tobias' Entangle pinned the swamp troll in place. Marching Song did more for this fight than the scoreboard shows. That was Hazel. Loot: 23 silver each, 4 troll hide, 10 herbs.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"bleakmarsh","fight":"f205","foes":["swamp_troll","swamp_troll"],"where":"on the road to Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-18,"wx":"rain"},{"id":"e2225","day":63,"season":3,"sday":3,"kind":"ambush","imp":2,"text":"The Black Vanguard wakes to 2 Will-o'-Wisps and a Swamp Troll in camp in Thornmere Ruins in the middle of the night, and handles them. Hazel's Crescendo dropped two will-o'-wisps before they reached the line. Ask the others what won it: Ash's Grave Command. Loot: 8 silver each, 1 troll hide, 4 bottled wisplight.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f206","foes":["swamp_troll","wisp","wisp"],"where":"at their camp in Thornmere Ruins, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-12,"wx":"storm"},{"id":"e2239","day":63,"season":3,"sday":3,"kind":"bond","imp":3,"text":"The Azure Gravediggers and The Black Vanguard are rivals now, starting with Morwen and Ash.","heroes":["h5","h12"],"parties":["p3","p5"],"bond":"rivals"},{"id":"e2243","day":63,"season":3,"sday":3,"kind":"tarot","imp":2,"text":"The Black Vanguard sit in a ring while Tobias turns the Pressed-Leaf Tarot for all of them before Thornmere Ruins: the Hermit, the Queen of Cups and the Ten of Cups. The cards are kind.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","reading":"r432","wx":"storm"},{"id":"e2263","day":64,"season":3,"sday":4,"kind":"delve","imp":1,"text":"The Black Vanguard descends into Thornmere Ruins, partly explored (41%), map in hand.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e2264","day":64,"season":3,"sday":4,"kind":"fight","imp":2,"text":"The Black Vanguard, in fine spirits lately, beats 3 Will-o'-Wisps and a Bog Crawler on floor 1 of Thornmere Ruins. One Crescendo from Hazel and three will-o'-wisps were on the ground. Tobias's Rootbound Ground turned the fight. Loot: 6 bottled wisplight, 4 chitin, 2 bog crawler claws.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f211","foes":["wisp","wisp","bog_crawler"],"where":"on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"storm"},{"id":"e2281","day":65,"season":3,"sday":5,"kind":"ambush","imp":2,"text":"In Thornmere Ruins, the Black Vanguard beats 3 Bounty Hunters and the Bounty Hunters' Captain, sent for the price on Hazel's head. Ash's Turn Undead went off among them; two of them stayed down. Marching Song came over Hazel at the right moment, as it does. Tobias shouted at the bodies for a while afterwards. Loot: 34 silver each, 6 stolen goods, 1 gem.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f213","foes":["bandit_captain","bandit","bandit"],"where":"in Thornmere Ruins, sent for the price on Hazel's head","won":true,"close":false,"shape":"hunted","reworded":-1,"wx":"storm"},{"id":"e2282","day":65,"season":3,"sday":5,"kind":"fight","imp":2,"text":"On floor 2 of Thornmere Ruins, the Black Vanguard squares up to 2 Swamp Trolls and 2 Will-o'-Wisps and carries the day. The last will-o'-wisp breaks and runs. Tobias' Thorn Whip found the swamp troll from the back row. Loot: 25 silver each, 3 troll hide, 4 herbs.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f214","foes":["swamp_troll","swamp_troll","wisp"],"where":"on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-39,"wx":"storm"},{"id":"e2285","day":65,"season":3,"sday":5,"kind":"meet","imp":1,"text":"The Black Vanguard and Amber Banner share a fire in Thornmere Ruins. There is a short argument about the best road to Ironhaven.","heroes":["h12","h8","h6","h18","h4","h2"],"parties":["p5","p2"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e2288","day":65,"season":3,"sday":5,"kind":"music","imp":3,"text":"The Black Vanguard sang \"Answer the Horn\" under a clear sky last night, and somewhere in the chorus it became their anthem. Ask any of them; they'll sing it for you.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","anthem":"answer_the_horn","night":"n107","wx":"storm"},{"id":"e2299","day":66,"season":3,"sday":6,"kind":"skim","imp":3,"text":"Tobias counts the haul twice, then looks at Ash. Ash hands back 28 silver without a word.","heroes":["h6","h12"],"parties":["p5"],"loc":"thornmere_ruins","in_fight":"f215","wx":"storm"},{"id":"e2300","day":66,"season":3,"sday":6,"kind":"fight","imp":2,"text":"It's 2 Swamp Trolls and a Bog Crawler against the Black Vanguard on floor 3 of Thornmere Ruins, and it isn't close. Radiance, from Ash, was the last thing the swamp troll saw. Without Tobias's Awaken the Grove, this goes differently. Loot: 30 silver each, 4 troll hide, 10 herbs.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f215","foes":["swamp_troll","bog_crawler","swamp_troll"],"where":"on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-13,"wx":"storm"},{"id":"e2301","day":66,"season":3,"sday":6,"kind":"artifact","imp":3,"text":"Hazel pockets a collar that fits any neck it wants to in Thornmere Ruins. Hazel feels stronger already.","heroes":["h8"],"parties":["p5"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e2319","day":66,"season":3,"sday":6,"kind":"song","imp":3,"text":"Somebody at The Honest Toll has written \"Who Took the Silver, Ash?\", and now nobody in Carrbridge can stop humming it. It tells of what Ash did in Thornmere Ruins.","heroes":["h12"],"parties":["p5"],"loc":"carrbridge","song":"s66_29"},{"id":"e2357","day":67,"season":3,"sday":7,"kind":"fight","imp":2,"text":"The Black Vanguard cuts down 2 Sirens, a Bog Crawler and a Swamp Troll on floor 3 of Thornmere Ruins, again. Before Hazel's Crescendo it could have gone either way. Loot: 14 silver each, 1 gem, 8 trinkets.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f223","foes":["siren","bog_crawler","siren"],"where":"on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"again","reworded":-7,"wx":"storm"},{"id":"e2358","day":67,"season":3,"sday":7,"kind":"treasure","imp":2,"text":"Mapping floor 3 of Thornmere Ruins, Tobias finds a forgotten storeroom. Inside: 493 silver and a gem.","heroes":["h6","h12","h8"],"parties":["p5"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e2389","day":68,"season":3,"sday":8,"kind":"fight","imp":2,"text":"With Hazel taking the worst of it, the Black Vanguard dispatches 2 Sirens and a Swamp Troll on floor 3 of Thornmere Ruins. Ash reached Hazel with Prayer of Healing with nothing to spare. Without Hazel's Marching Song, this goes differently. Loot: 14 silver each, 1 gem, 2 troll hide. Injured: Hazel (bruised ribs).","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f226","foes":["siren","swamp_troll","siren"],"where":"on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-35,"wx":"rain"},{"id":"e2416","day":69,"season":3,"sday":9,"kind":"fight","imp":1,"text":"The Black Vanguard meets 2 Drakes on floor 4 of Thornmere Ruins and beats them. The last drake doesn't stay to see the end. The drake was already dying of Tobias' Thorn Whip before it knew it. Loot: 1 drake scale, 4 fangs & claws.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f230","foes":["drake","drake"],"where":"on floor 4 of Thornmere Ruins","won":true,"close":false,"shape":"plain","reworded":-37,"wx":"rain"},{"id":"e2417","day":69,"season":3,"sday":9,"kind":"treasure","imp":1,"text":"Hazel jimmies open a chest on floor 4 of Thornmere Ruins: 92 silver, a gem and an unidentified relic.","heroes":["h8","h12","h6"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e2432","day":70,"season":3,"sday":10,"kind":"curse","imp":4,"text":"Something is wrong with The Black Vanguard. Since Hazel picked up the Hound's Collar, nobody trusts anybody, and Hazel won't put it down.","heroes":["h8"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e2446","day":70,"season":3,"sday":10,"kind":"skim","imp":1,"text":"Hazel counts the haul twice, then looks at Ash. Ash hands back 10 silver without a word.","heroes":["h8","h12"],"parties":["p5"],"loc":"thornmere_ruins","in_fight":"f233"},{"id":"e2447","day":70,"season":3,"sday":10,"kind":"skim","imp":1,"text":"The Black Vanguard sits Ash down by the fire. Twice now. Nobody shouts. That's what makes it bad. One more time and they are out.","heroes":["h8","h6","h12"],"parties":["p5"],"loc":"thornmere_ruins","in_fight":"f233"},{"id":"e2448","day":70,"season":3,"sday":10,"kind":"fight","imp":2,"text":"It takes the Black Vanguard 6 rounds to outlast 2 Drakes and a Swamp Troll on floor 4 of Thornmere Ruins. Tobias tied up the drake with Entangle at just the right moment. Ash kept everyone standing (339 healed, Prayer of Healing doing the heavy lifting). Loot: 9 silver each, 4 drake flanks, 1 troll hide.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f233","foes":["drake","swamp_troll","drake"],"where":"on floor 4 of Thornmere Ruins","won":true,"close":true,"shape":"close","reworded":-20},{"id":"e2449","day":70,"season":3,"sday":10,"kind":"ability","imp":2,"text":"Hazel hums the victory verse under their breath while picking up their axe at Thornmere Ruins. By the last line the cut on their arm has stopped stinging.","heroes":["h8"],"parties":["p5"],"loc":"thornmere_ruins","skill":"victory_verse","sk":"The Victory Verse","rule":true},{"id":"e2450","day":70,"season":3,"sday":10,"kind":"treasure","imp":1,"text":"Ash jimmies open a chest on floor 4 of Thornmere Ruins: 346 silver and an unidentified relic.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e2451","day":70,"season":3,"sday":10,"kind":"talent","imp":1,"text":"A fox sits at the edge of the firelight and Tobias talks to it for an hour. It leaves happier than it came.","heroes":["h6"],"parties":["p5"],"loc":"thornmere_ruins","skill":"wild_tongue"},{"id":"e2458","day":70,"season":3,"sday":10,"kind":"song","imp":3,"text":"\"Run, Ash, Run\" is the new song at The Honest Toll. It's about what Ash did in Thornmere Ruins. The keeper has already heard it nine times and is starting to like it.","heroes":["h12"],"parties":["p5"],"loc":"carrbridge","song":"s70_31"},{"id":"e2461","day":70,"season":3,"sday":10,"kind":"gift","imp":2,"text":"Hazel admired Tobias's Bell off a Cat's Collar one too many times. Now it's Hazel's.","heroes":["h6","h8"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e2489","day":71,"season":3,"sday":11,"kind":"fight","imp":2,"text":"On floor 4 of Thornmere Ruins, a Drake and a Swamp Troll get in the Black Vanguard's way, briefly. Tobias' Thorn Whip put poison in the drake, and it did its slow work. Loot: 13 silver each, 2 drake scales, 2 drake flanks.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f237","foes":["drake","swamp_troll"],"where":"on floor 4 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-14},{"id":"e2491","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"Hazel lays out their pilgrim tokens by the fire and tells Tobias where each one came from. That's Pilgrim for you.","heroes":["h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","skill":"pilgrim"},{"id":"e2498","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"A ceiling comes down exactly where Ash was standing a moment before.","heroes":["h12"],"parties":["p5"],"loc":"thornmere_ruins","skill":"death_keeps_missing"},{"id":"e2515","day":71,"season":3,"sday":11,"kind":"goal","imp":1,"text":"The Black Vanguard sets their sights for the season: to earn 3,050 silver between them before the season ends.","heroes":["h12","h8","h6"],"parties":["p5"]},{"id":"e2541","day":72,"season":3,"sday":12,"kind":"delve_done","imp":1,"text":"The Black Vanguard comes up after 9 days in Thornmere Ruins. They got as far as Mother Thornmere's Brood's door, but no further, mapped 100% of it, found a forgotten storeroom and came away with 1382 silver between them. Counting everyone's digging, Thornmere Ruins is mostly explored (89%).","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","days":9,"bottom":false,"rooms":["a forgotten storeroom"],"gold":1382,"wx":"fog"},{"id":"e2542","day":72,"season":3,"sday":12,"kind":"boss_race","imp":2,"text":"The Black Vanguard gives up on Mother Thornmere's Brood for now, and the race to Thornmere Ruins belongs to Amber Banner.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2543","day":72,"season":3,"sday":12,"kind":"gift","imp":2,"text":"The Bandit's Hidden Coin changes hands again: Hazel to Ash this time. It has been passed around this crew 2 times now.","heroes":["h8","h12"],"parties":["p5"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2550","day":72,"season":3,"sday":12,"kind":"talent","imp":1,"text":"Tobias hums with the wind in the pines until Hazel falls asleep.","heroes":["h6","h8"],"parties":["p5"],"loc":"thornmere_ruins","skill":"word_on_the_wind","wx":"fog"},{"id":"e2573","day":73,"season":3,"sday":13,"kind":"road","imp":3,"text":"Mother Wort leads Hazel through a bramble tunnel, which the goblin calls the Quick Way. It is quick, in the sense of being mostly downhill.","heroes":["h8","h12","h6"],"parties":["p5"],"road":"bleakmarsh~thornmere_ruins","traveller":"muddy_boot","road_rec":"r480"},{"id":"e2578","day":73,"season":3,"sday":13,"kind":"meet","imp":2,"text":"The Black Vanguard warns The Newts of Ashfen about what's lurking in Bleakmarsh. The Newts of Ashfen pretend to already know.","heroes":["h12","h8","h6","h13","h7"],"parties":["p5","p1"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2579","day":73,"season":3,"sday":13,"kind":"talent","imp":1,"text":"Tobias tells the party it'll rain in an hour. It rains in an hour.","heroes":["h6"],"parties":["p5"],"loc":"bleakmarsh","skill":"word_on_the_wind","wx":"fog"},{"id":"e2580","day":73,"season":3,"sday":13,"kind":"ability","imp":2,"text":"Tobias puts their ear to an old oak at the roadside. The oak has heard from the other oaks. Tobias now knows the prices in towns far off.","heroes":["h6"],"parties":["p5"],"loc":"bleakmarsh","skill":"word_on_the_wind","sk":"Word on the Wind","rule":true,"wx":"fog"},{"id":"e2582","day":73,"season":3,"sday":13,"kind":"talent","imp":1,"text":"Ash dreams of a hooded figure tapping its foot, rolls over and goes back to sleep.","heroes":["h12"],"parties":["p5"],"loc":"bleakmarsh","skill":"death_keeps_missing","wx":"fog"},{"id":"e2583","day":73,"season":3,"sday":13,"kind":"campfire","imp":2,"text":"Clementine the cat won't sleep unless Hazel is in sight. Nobody can explain it.","heroes":["h12","h8"],"parties":["p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2598","day":74,"season":3,"sday":14,"kind":"bounty","imp":2,"text":"The guild clerk in Carrbridge counts out bounties for The Black Vanguard until the cashbox is empty: 93 silver each.","heroes":["h12"],"parties":["p5"],"loc":"carrbridge","amount":93,"wx":"rain"},{"id":"e2621","day":74,"season":3,"sday":14,"kind":"talent","imp":1,"text":"Carrbridge children follow Hazel through the streets singing the victory verse back, wrongly. (The Victory Verse, if anyone's asking.)","heroes":["h8"],"parties":["p5"],"loc":"carrbridge","skill":"victory_verse","wx":"rain"},{"id":"e2633","day":74,"season":3,"sday":14,"kind":"ledger","imp":2,"text":"Counters and coin this week: 16 sales, 1,962 silver changing hands. Biggest haul: Hazel, 500 silver in Carrbridge. Back up from the deep: The Mercy of Thornwall (6 days in the Ashveil Crypts), The Black Vanguard (9 days in Thornmere Ruins).","heroes":["h8","h17","h12"],"parties":["p4","p5"]},{"id":"e2634","day":74,"season":3,"sday":14,"kind":"big_move","imp":3,"text":"Carrbridge has a new homeowner: Hazel, 630 silver lighter, takes a cottage. On the table: Hazel +78 renown (8th to 4th). The Black Vanguard +58 party renown (holds 3rd among the crews).","heroes":["h8"],"parties":["p5"],"cause":"e2601","moves":[{"hero":"h8","gain":78,"from":8,"to":4}],"party_moves":[{"party":"p5","gain":58,"from":3,"to":3}]},{"id":"e2669","day":75,"season":3,"sday":15,"kind":"argument","imp":2,"text":"Hazel and Tobias are not speaking. It's about who lost the map. It's never really about who lost the map.","heroes":["h8","h6"],"parties":["p5"]},{"id":"e2670","day":75,"season":3,"sday":15,"kind":"campfire","imp":1,"text":"Clementine the cat has chosen Hazel. Hazel pretends to mind. Ash is quietly delighted.","heroes":["h12","h8"],"parties":["p5"],"loc":"thornwall","wx":"rain"},{"id":"e2677","day":76,"season":3,"sday":16,"kind":"road","imp":3,"text":"Sister Rue and Tobias start a friendly swearing contest on the road. Tobias gives a good account of himself. Sister Rue wins by a mile and three syllables.","heroes":["h6","h12","h8"],"parties":["p5"],"road":"hollowood~thornwall","traveller":"rue","road_rec":"r491"},{"id":"e2709","day":77,"season":3,"sday":17,"kind":"curse","imp":2,"text":"Hazel snaps at a barkeep over nothing, then stares at the Hound's Collar for an hour. The curse is winning, for now.","heroes":["h8"],"parties":["p5"],"loc":"thornwall","wx":"rain"},{"id":"e2713","day":77,"season":3,"sday":17,"kind":"road","imp":2,"text":"The drover on the road to Hollowood catches Ash with a hand in the cart and shouts for the whole road to hear. Ash runs, and the word runs faster.","heroes":["h12","h6","h8"],"parties":["p5"],"road":"hollowood~thornwall","road_rec":"r495"},{"id":"e2740","day":77,"season":3,"sday":17,"kind":"gift","imp":4,"text":"Hazel could have sold Grimoire of Margin Notes for a small fortune. Instead it goes to Tobias, who can actually use it.","heroes":["h8","h6"],"parties":["p5"],"loc":"hollowood","wx":"storm"},{"id":"e2754","day":77,"season":3,"sday":17,"kind":"goal_progress","imp":2,"text":"The Black Vanguard is getting close: earn 3,050 silver between them before the season ends (1,938 of 3,050 silver).","heroes":["h12","h8","h6"],"parties":["p5"]},{"id":"e2759","day":78,"season":3,"sday":18,"kind":"contract","imp":2,"text":"The Black Vanguard takes a job that isn't on the board in Hollowood: three sacks of what are definitely not stolen candlesticks, to Carrbridge. The pay is very good. That's the worrying part.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"hollowood"},{"id":"e2760","day":78,"season":3,"sday":18,"kind":"escort","imp":1,"text":"The Black Vanguard ties down three sacks of what are definitely not stolen candlesticks with borrowed rope, checks it twice, and sets off from Hollowood for Thornwall before midday.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"hollowood"},{"id":"e2762","day":78,"season":3,"sday":18,"kind":"party_life","imp":1,"text":"Tobias arrives in the ox wagon with straw in his hair and a face like thunder.","heroes":["h6"],"parties":["p5"],"loc":"hollowood"},{"id":"e2763","day":78,"season":3,"sday":18,"kind":"road","imp":3,"text":"The tinkers rummage through the wagon and give Tobias a trinket, wrapped in a sock, which they say is the proper way.","heroes":["h6","h12","h8"],"parties":["p5"],"road":"hollowood~thornwall","traveller":"kettleby","road_rec":"r500"},{"id":"e2764","day":78,"season":3,"sday":18,"kind":"escort","imp":1,"text":"A buyer at a crossroads on the road to Thornwall offers good silver for the cargo, on the spot. The Black Vanguard says no. It isn't theirs to sell.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"hollowood"},{"id":"e2775","day":78,"season":3,"sday":18,"kind":"ability","imp":2,"text":"A pedlar with a bad leg and a worse donkey asks Ash to walk with them past Hollowood. Ash carries the donkey's load half the way, learns a lot about pots, and is paid 29 silver at the gate.","heroes":["h12"],"parties":["p5"],"loc":"hollowood","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true},{"id":"e2780","day":78,"season":3,"sday":18,"kind":"ability","imp":1,"text":"A flock of starlings swirls over the road. Tobias reads them like a market board and tells Ash the price of fish three towns away.","heroes":["h6","h12"],"parties":["p5"],"loc":"hollowood","skill":"word_on_the_wind","sk":"Word on the Wind","rule":true},{"id":"e2785","day":78,"season":3,"sday":18,"kind":"campfire","imp":1,"text":"Hazel tells Tobias something they've never told anyone. Tobias keeps it.","heroes":["h6","h8"],"parties":["p5"],"loc":"hollowood"},{"id":"e2798","day":79,"season":3,"sday":19,"kind":"escort","imp":1,"text":"The Black Vanguard counts the cargo at every milestone on the road to Thornwall. Still all there.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"hollowood","wx":"fog"},{"id":"e2814","day":79,"season":3,"sday":19,"kind":"argument","imp":1,"text":"Tobias and Ash are not speaking. It's about how the loot was split. It's never really about how the loot was split.","heroes":["h6","h12"],"parties":["p5"]},{"id":"e2834","day":80,"season":3,"sday":20,"kind":"road","imp":2,"text":"Ash hears a faint humming on the road to Carrbridge and follows it to the Lantern Lady of Gallows Cross, for the first time, who stops as soon as she is noticed.","heroes":["h12","h6","h8"],"parties":["p5"],"road":"carrbridge~thornwall","traveller":"lantern_lady","road_rec":"r527"},{"id":"e2835","day":80,"season":3,"sday":20,"kind":"escort","imp":1,"text":"The Black Vanguard stops on the road to Carrbridge to retie the whole load, properly this time. It takes an hour and is worth it.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"thornwall","wx":"rain"},{"id":"e2836","day":80,"season":3,"sday":20,"kind":"contract","imp":2,"text":"The Black Vanguard hands over three sacks of what are definitely not stolen candlesticks in Carrbridge. Nobody asks. The Black Vanguard is paid 74 silver each by a man who was never here.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"carrbridge","wx":"rain"},{"id":"e2846","day":80,"season":3,"sday":20,"kind":"campfire","imp":2,"text":"Tobias buys Hazel a mystery stew. Then another. Then the conversation gets honest.","heroes":["h6","h8"],"parties":["p5"],"loc":"carrbridge","wx":"rain"},{"id":"e2876","day":81,"season":3,"sday":21,"kind":"night","imp":1,"text":"A child turns up at The Black Vanguard's camp in Bleakmarsh, announces that the Sunken Vault \"eats lanterns\", and runs off before anyone can ask what that means.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2886","day":81,"season":3,"sday":21,"kind":"argument","imp":1,"text":"It starts with whose idea the last dungeon was. It ends with Ash and Tobias sleeping on opposite sides of the fire.","heroes":["h12","h6"],"parties":["p5"]},{"id":"e2888","day":81,"season":3,"sday":21,"kind":"campfire","imp":1,"text":"Ash lends Tobias a whetstone. It comes back cleaner than it left.","heroes":["h12","h6"],"parties":["p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2910","day":82,"season":3,"sday":22,"kind":"ability","imp":2,"text":"A line of nuns on the road past Bleakmarsh ask Ash to see them over the hill. Ash does, singing all three of their hymns badly. They give 40 silver and a long list of corrections.","heroes":["h12"],"parties":["p5"],"loc":"bleakmarsh","skill":"pilgrims_escort","sk":"The Pilgrims' Escort","rule":true,"wx":"fog"},{"id":"e2914","day":82,"season":3,"sday":22,"kind":"campfire","imp":1,"text":"Tobias and Ash walk point together all afternoon and say about nine words. Good words.","heroes":["h6","h12"],"parties":["p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2924","day":83,"season":3,"sday":23,"kind":"fight","imp":2,"text":"With Ash keeping everyone up, the Black Vanguard dispatches a Will-o'-Wisp, Risen Dead and a Swamp Troll in Bleakmarsh. Two fights at once: the dead and the troll were already at each other's throats when The Black Vanguard walked into the middle of it. It was Ash's Smite that dropped the risen dead. Awaken the Grove, from Tobias, at exactly the right moment. Loot: 9 silver each, 2 bottled wisplight, 2 wisp sugar.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"bleakmarsh","fight":"f265","foes":["wisp","zombie","swamp_troll"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"hero","reworded":-30,"wx":"fog"},{"id":"e2950","day":83,"season":3,"sday":23,"kind":"talent","imp":1,"text":"Ash follows a bee across a meadow to a hollow tree and returns with honeycomb and three stings. Honey Finder: a ranger's patience, mostly.","heroes":["h12"],"parties":["p5"],"loc":"bleakmarsh","skill":"honey_finder","wx":"fog"},{"id":"e2951","day":83,"season":3,"sday":23,"kind":"talent","imp":2,"text":"Tobias pulls a handful of yarrow from a field edge and stuffs it in a pouch. 'For later. You'll see.' Every archdruid learns Herbalism sooner or later. Not every archdruid learns it like that.","heroes":["h6"],"parties":["p5"],"loc":"bleakmarsh","skill":"herbalism","wx":"fog"},{"id":"e2954","day":83,"season":3,"sday":23,"kind":"argument","imp":2,"text":"It starts with who ate the last of the cheese. It ends with Ash and Tobias sleeping on opposite sides of the fire.","heroes":["h12","h6"],"parties":["p5"]},{"id":"e2961","day":84,"season":3,"sday":24,"kind":"curse","imp":3,"text":"Hazel snaps at a barkeep over nothing, then stares at the Hound's Collar for an hour. The curse is winning, for now.","heroes":["h8"],"parties":["p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2978","day":84,"season":3,"sday":24,"kind":"talent","imp":1,"text":"The Carrbridge tavern's famously vicious guard dog puts its head in Tobias's lap. The regulars are unsettled. Somebody asks how. 'Animal Handler,' says Tobias.","heroes":["h6"],"parties":["p5"],"loc":"carrbridge","skill":"animal_handler"},{"id":"e2997","day":85,"season":3,"sday":25,"kind":"road","imp":4,"text":"From a high balcony, Lady Perpetua Vane calls down thanks to Tobias before the whole street, and tells everyone she found the way herself.","heroes":["h6","h12","h8"],"parties":["p5"],"road":"carrbridge~ironhaven","traveller":"perpetua","road_rec":"r558"},{"id":"e3009","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Ash gives a pilgrim their bed in an Ironhaven inn and sleeps in the stable.","heroes":["h12"],"parties":["p5"],"loc":"ironhaven","skill":"pilgrims_escort"},{"id":"e3048","day":86,"season":3,"sday":26,"kind":"ability","imp":2,"text":"A gust near Frosthold brings Tobias the smell of the coast, the river ports and a market in full cry. Tobias names the prices out loud, and the party walks the rest of the day with a spring in its step.","heroes":["h6"],"parties":["p5"],"loc":"frosthold","skill":"word_on_the_wind","sk":"Word on the Wind","rule":true,"wx":"fog"},{"id":"e3057","day":87,"season":3,"sday":27,"kind":"curse","imp":5,"text":"Father Hoarfrost takes the Hound's Collar from Hazel's shaking hands, says some very old words over it, and breaks it. 60 silver, and worth every coin.","heroes":["h8"],"parties":["p5"],"loc":"frosthold","wx":"fog"},{"id":"e3072","day":87,"season":3,"sday":27,"kind":"road","imp":2,"text":"Sergeant Hobb Withy snaps to attention when Hazel comes by for the first time, and then pretends he was only stretching his back.","heroes":["h8","h12","h6"],"parties":["p5"],"road":"frosthold~ironhaven","traveller":"withy","road_rec":"r576"},{"id":"e3127","day":89,"season":3,"sday":29,"kind":"contract","imp":2,"text":"A man in Frosthold who doesn't give his name pays The Black Vanguard to move three sacks of what are definitely not stolen candlesticks to Veldrock. Half now, half on arrival, no questions.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"frosthold","wx":"snow"},{"id":"e3128","day":89,"season":3,"sday":29,"kind":"escort","imp":1,"text":"The Black Vanguard walks three sacks of what are definitely not stolen candlesticks out through the Frosthold gate and onto the road to Veldrock by noon.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"frosthold","wx":"snow"},{"id":"e3142","day":89,"season":3,"sday":29,"kind":"gift","imp":2,"text":"The Bell off a Cat's Collar changes hands again: Hazel to Ash this time. It has been passed around this crew 2 times now.","heroes":["h8","h12"],"parties":["p5"],"loc":"frosthold","wx":"snow"},{"id":"e3152","day":89,"season":3,"sday":29,"kind":"argument","imp":2,"text":"Tobias says one thing too many about the ethics of looting bodies. Ash says two.","heroes":["h6","h12"],"parties":["p5"]},{"id":"e3153","day":89,"season":3,"sday":29,"kind":"campfire","imp":2,"text":"Tobias and Ash sit on opposite sides of The Third Coat and end up, somehow, on the same side.","heroes":["h6","h12"],"parties":["p5"],"loc":"frosthold","wx":"snow"},{"id":"e3163","day":90,"season":3,"sday":30,"kind":"escort","imp":1,"text":"The Black Vanguard walks beside the cargo the whole way on the road to Veldrock, one hand on it, as if it might wander off.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"frosthold","wx":"snow"},{"id":"e3164","day":90,"season":3,"sday":30,"kind":"contract","imp":2,"text":"A back door in Veldrock, a knock, a purse: The Black Vanguard delivers three sacks of what are definitely not stolen candlesticks and collects 58 each. The less said the better.","heroes":["h12","h8","h6"],"parties":["p5"],"loc":"veldrock","wx":"snow"},{"id":"e3188","day":90,"season":3,"sday":30,"kind":"argument","imp":1,"text":"Ash and Tobias of The Black Vanguard have a shouting match about how the loot was split.","heroes":["h12","h6"],"parties":["p5"]},{"id":"e3202","day":90,"season":3,"sday":30,"kind":"goal_missed","imp":3,"text":"Not this time: The Black Vanguard's goal (earn 3,050 silver between them before the season ends) falls short (2,974 of 3,050 silver).","heroes":["h12","h8","h6"],"parties":["p5"]},{"id":"e3208","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Newts of Ashfen, to share every coin (sworn in season 2); Amber Banner, to die rich (sworn in season 2); The Mercy of Thornwall, to keep the peace: never draw first on another hero (sworn in season 2); The Mercy of Thornwall, to die rich (sworn in season 2); The Black Vanguard, never to retreat (sworn in season 2); The Green Mercy, to keep the peace: never draw first on another hero (sworn in season 1); Vex, to keep the peace: never draw first on another hero (sworn in season 1). Every one of them held.","heroes":["h7"],"parties":["p1","p2","p4","p5","p6"]}],"roles":{"h6":"Tracker","h12":"Leader · Healer","h8":"Face"},"quest":{"what":"Escort","where":"Veldrock","why":"moving three sacks of what are definitely not stolen candlesticks to Veldrock, no questions asked","floor":null,"floors":null},"tactics":{"front":["h12","h8"],"back":["h6"],"plan":"Ash and Hazel hold the front; Tobias casts from behind; Ash keeps everyone standing.","traits":{"boldness":0.38,"risk":0.02,"greed":-0.09,"sociability":-0.34,"honor":-0.21,"curiosity":0.12,"temper":0.29,"loyalty":-0.1},"mix":"1 blade, 1 talker, 1 caster","notes":[],"style":["bold","balanced"],"skills":[{"label":"Damage","skills":[{"hero":"h6","id":"thorn_whip","name":"Thorn Whip","desc":"A vine with ideas.","tags":["nature"],"rank":2,"uses":38},{"hero":"h8","id":"crescendo","name":"Crescendo","desc":"The song builds and builds until the enemy can't hear themselves think.","tags":[],"rank":1,"uses":28},{"hero":"h12","id":"turn_undead","name":"Turn Undead","desc":"Begone.","tags":["holy"],"rank":3,"uses":25},{"hero":"h12","id":"radiance","name":"Radiance","desc":"A flash of holy light, right in the eyes.","tags":["holy"],"rank":3,"uses":20},{"hero":"h12","id":"smite","name":"Smite","desc":"Radiant and righteous. Double against the dead.","tags":["holy"],"rank":1,"uses":1}]},{"label":"Healing","skills":[{"hero":"h12","id":"prayer_of_healing","name":"Prayer of Healing","desc":"Everybody, bow your heads.","tags":["holy","heal"],"rank":1,"uses":8}]},{"label":"Defence","skills":[{"hero":"h6","id":"barkskin","name":"Barkskin","desc":"Skin goes knotted and brown. It's fine. It's fine.","tags":["nature","guard"],"rank":3,"uses":30},{"hero":"h8","id":"inspire","name":"Inspire","desc":"A verse about how great they all are. Bruises feel smaller.","tags":["command"],"rank":2,"uses":26},{"hero":"h12","id":"divine_shield","name":"Divine Shield","desc":"Golden light, briefly.","tags":["holy","guard"],"rank":3,"uses":23},{"hero":"h8","id":"saga_of_fury","name":"Saga of Fury","desc":"Three verses, each angrier. Nobody waits for the fourth.","tags":["rage","music"],"rank":2,"uses":16},{"hero":"h8","id":"war_chant","name":"War Chant","desc":"A song with a body count.","tags":["music","rage"],"rank":1,"uses":15},{"hero":"h8","id":"rousing_ballad","name":"Rousing Ballad","desc":"Four verses about how this all ends well.","tags":["music"],"rank":1,"uses":0}]},{"label":"Tricks","skills":[{"hero":"h8","id":"marching_song","name":"Marching Song","desc":"Everybody steps off on the same foot.","tags":["music","travel"],"rank":3,"uses":30},{"hero":"h6","id":"entangle","name":"Entangle","desc":"Roots burst from the floor.","tags":["nature"],"rank":3,"uses":23},{"hero":"h12","id":"grave_command","name":"Grave Command","desc":"Calls the old soldiers up for one more shift.","tags":["death"],"rank":1,"uses":11},{"hero":"h6","id":"rootbound_ground","name":"Rootbound Ground","desc":"Outnumbered is just a word for more ankles.","tags":[],"rank":1,"uses":11},{"hero":"h6","id":"awaken_the_grove","name":"Awaken the Grove","desc":"The trees were only waiting to be asked.","tags":["nature"],"rank":2,"uses":11},{"hero":"h12","id":"death_keeps_missing","name":"Death Keeps Missing","desc":"Has an understanding with the Reaper. The Reaper is not happy about it.","tags":[],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h12","id":"steady_nerves","name":"Steady Nerves","desc":"Doesn't flinch. Neither does the party.","tags":["holy"],"rank":1,"uses":0},{"hero":"h8","id":"aura_of_courage","name":"Aura of Courage","desc":"Nobody runs while they stand.","tags":["holy","command"],"rank":1,"uses":0},{"hero":"h6","id":"oakheart","name":"Oakheart","desc":"Has rings. Won't say how many.","tags":["nature"],"rank":2,"uses":0}]},{"label":"On the road","skills":[{"hero":"h12","id":"devout","name":"Devout","desc":"Temples patch them up for less.","tags":["holy"],"rank":1,"uses":0},{"hero":"h12","id":"hymn_singer","name":"Hymn Singer","desc":"Sings the old hymns in a voice like a warm bath.","tags":["holy","music"],"rank":2,"uses":0},{"hero":"h12","id":"firekeeper","name":"Firekeeper","desc":"Lights a fire in a rainstorm, with wet wood, every time.","tags":[],"rank":1,"uses":0},{"hero":"h12","id":"honey_finder","name":"Honey Finder","desc":"Follows the bees. Comes back sticky.","tags":[],"rank":1,"uses":0},{"hero":"h12","id":"wayside_shrines","name":"Wayside Shrines","desc":"Sweeps out every roadside shrine. The priests start leaving the door open.","tags":["holy"],"rank":1,"uses":0},{"hero":"h12","id":"grave_tender","name":"Grave Tender","desc":"Tidies forgotten graves. The dead appreciate it.","tags":["death","holy"],"rank":1,"uses":0},{"hero":"h8","id":"cobbler","name":"Cobbler","desc":"New soles for old boots, old roads for new soles.","tags":["craft","travel"],"rank":1,"uses":0},{"hero":"h8","id":"supply_master","name":"Supply Master","desc":"Gets supplies at cost.","tags":["trade"],"rank":1,"uses":0},{"hero":"h8","id":"scrying","name":"Scrying","desc":"Peers into a bowl of water and sees tomorrow, blurry.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h8","id":"market_gossip","name":"Market Gossip","desc":"Knows what pepper costs in three towns.","tags":["trade"],"rank":1,"uses":0},{"hero":"h8","id":"tavern_star","name":"Tavern Star","desc":"Packs every inn. Drinks are free.","tags":["music","trade"],"rank":2,"uses":0},{"hero":"h8","id":"mead_hall","name":"Mead Hall","desc":"Out-sings and out-drinks the whole hall. Collects the bets on both.","tags":["rage","music"],"rank":1,"uses":0},{"hero":"h8","id":"gambler","name":"Gambler","desc":"Dice nights are profitable. Usually.","tags":[],"rank":1,"uses":0},{"hero":"h8","id":"pilgrim","name":"Pilgrim","desc":"Every road leads to a shrine, if you walk it right.","tags":["holy","travel"],"rank":1,"uses":0},{"hero":"h8","id":"mushroom_hunter","name":"Mushroom Hunter","desc":"Knows which ones are dinner and which ones are a funeral.","tags":[],"rank":1,"uses":0},{"hero":"h6","id":"wild_tongue","name":"Wild Tongue","desc":"Asks the birds. The birds know a shortcut.","tags":["nature"],"rank":1,"uses":0},{"hero":"h6","id":"herbalism","name":"Herbalism","desc":"Knows every useful leaf.","tags":["nature","heal"],"rank":3,"uses":0},{"hero":"h6","id":"animal_handler","name":"Animal Handler","desc":"Horses calm down. Dogs sit. Geese reconsider.","tags":["beast","nature"],"rank":1,"uses":0},{"hero":"h6","id":"angler","name":"Angler","desc":"Has a line in the water before the tent is up.","tags":[],"rank":1,"uses":0},{"hero":"h6","id":"horse_whisperer","name":"Horse Whisperer","desc":"Horses don't go lame on their watch, and thieves can't lead one off.","tags":["ride","beast"],"rank":1,"uses":0},{"hero":"h6","id":"packmule","name":"Packmule","desc":"Carries half again as much.","tags":[],"rank":1,"uses":0}]}],"share":[{"hero":"h12","dmg":2180,"healed":952,"taken":463,"kills":11,"row":"front"},{"hero":"h8","dmg":2108,"healed":92,"taken":597,"kills":8,"row":"front"},{"hero":"h6","dmg":2021,"healed":0,"taken":131,"kills":10,"row":"back"}],"ground":{"name":"Thornmere Ruins","fights":19}},"trophies":[{"boss":"Old Grizzlemaw","monster":"cave_bear","place":"The Wolf Den","day":10,"season":1,"fight":"f48"}]};